    public static function key(string $source):string{return 'manual_finance_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array
    {
        $english=explode('-',$locale,2)[0]==='en';$messages=[];foreach(self::ENGLISH as $source=>$translation)$messages[self::key($source)]=$english?$translation:$source;return $messages;
    }
    public static function text(string $source,array $messages,array $values=[]):string
    {
        if(preg_match('/\A(Ideeller Bereich|Vermögensverwaltung|Zweckbetrieb|Wirtschaftlicher Geschäftsbetrieb) · Unterteilung ([1-4][1-9])\z/D',$source,$parts))return self::text('{area} · Unterteilung {code}',$messages,['area'=>self::text($parts[1],$messages),'code'=>$parts[2]]);
        $text=$messages[self::key($source)]??FinanceMatchingMessages::text($source,$messages);
        if($text===$source&&!isset(self::ENGLISH[$source]))$text=DocumentMessages::text($source,$messages);
        return strtr($text,array_combine(array_map(static fn($key)=>'{'.$key.'}',array_keys($values)),array_values($values)));
    }
    public static function client(array $messages):array
    {
        $out=[];foreach(self::ENGLISH as $source=>$translation)$out[$source]=self::text($source,$messages);return $out;
    }
}
